A0 = np.array([[-19.83026583,8.46737769,-20.92202447,8.149774299,4.877472604,0.1443601361,3.020569051,0.9832596542],[14.42143647,-0.7085655018,12.31931303,-14.21513857,-5.495678963,-1.027148128,-0.6829795809,1.000702071],[6.347615305,3.110521862,-0.6962774355,-5.050713244,-9.76552801,-11.38394788,2.894516091,0.3531619423],[6.093975311,2.403705348,2.481987523,-4.321743479,-8.134003445,-8.807399313,-2.48612735,-3.16576828],[55.47594999,-74.64248162,65.27210935,32.03352224,10.63254996,40.05957532,-10.37247889,1.533802024],[-21.34609945,6.215710767,-14.6117312,13.27069487,10.89995683,3.808990675,1.432010264,0.629142372],[-5.808645057,-1.881369431,-1.962491442,8.357812292,2.586155387,3.149811887,1.419275152,1.610027422],[-4.442880415,4.495247021,8.469573023,4.520200782,-7.202890354,-6.487689917,3.4312342,1.286940298]])
VO0 = np.array([[1.148265441,0.006866611507,-0.3601884469,0.1388765891,-0.009895275525,0.2797888762,0.621144982,1.390405644],[-1.886425606,-1.337204637,0.4955196698,-0.464047615,-0.07174115754,-0.4110467995,0.3112013353,0.8949762878],[-1.864668061,-2.321442509,0.2239517265,-0.9673094885,-0.2091800166,-0.7430724237,-0.3742554761,-0.6507937823],[-0.675339091,0.7848049711,0.271226045,1.17772122,-0.1469494839,-0.04854650595,-0.5083026491,-0.02390104463],[0.2945958645,2.458256954,0.219802067,2.227717437,-0.09822023788,0.4705883405,2.595664798,2.795156489],[3.405931868,0.2427080784,-1.282167451,-2.800099207,0.5238195452,-0.004507706428,-3.620265936,-8.448161389],[-0.4306633454,-0.02869271206,0.1512833457,0.2406820839,-0.05197367049,-0.08814860324,0.2222004329,0.05675148736],[0.05019763659,0.05984483188,0.01563101908,-0.02183019542,0.02337245418,0.04773873662,-0.08072843597,0.04404422383]])
A1 = np.array([[0.7022135673,0.06810541508,-1.708665673,3.926392435,-12.39880954,-5.190894859,-1.805291121,-1.225051036],[-0.2372787855,-1.949698894,3.385908004,-1.014660808,-1.62806479,8.749104405,0.2661846007,0.05178615681],[-1.66752551,-4.014008912,-5.057195741,7.016490014,-48.35748817,14.96327059,-4.503875436,-3.33779971],[-1.711552311,2.350284374,-4.877208968,-1.655984527,11.12916133,-3.577656112,0.9392158107,0.8700469151],[-1.208787515,2.343163442,-2.030049277,-5.731149284,31.07189258,-2.361268365,3.57385762,1.535936352],[3.362817117,-0.1577733552,2.267413645,1.3490764,-8.480249155,-7.985869758,-0.5890156228,-0.2904016185],[0.05331281698,-0.1509787918,-0.02993953615,0.2435629854,0.8224652833,-0.4119060649,0.0536000055,-0.108593414],[-0.3570862952,0.403465206,-0.000629790702,-0.2911626536,0.4796966403,0.5072293517,-0.09872595318,0.09646004966]])
G = np.array([[-0.7079269424,-8.767990078,-10.56343602],[4.081446833,3.237097542,3.836126363],[-6.520562786,-24.70837868,-30.07298582],[0.5808402255,3.471537113,2.867156678],[6.953796795,17.84669692,18.15256893],[-16.0874562,-8.6240909,-7.134359961],[-0.8632829475,-1.127352013,-1.187546135],[2.078451564,1.957478037,2.007224693]])
H = np.array([[17.23709504,6.144665382,3.688296274],[-37.42980294,-23.20763377,-18.21367998],[-2.493335888,-1.39352765,-1.232385097],[2.021996119,3.216277466,2.85996722],[-141.9362524,-63.68692468,-47.95114251],[58.97058343,36.56592692,28.68480426],[1.212322035,3.27272783,2.960728601],[-9.531256296,-7.437466558,-6.345723937]])

P = np.concatenate([np.eye(6), np.zeros((6, 2))], 1)

def model(x, iv):
    x = np.asarray(x).astype(int)
    B = x.shape[0]
    E = np.eye(6)
    tok = [iv("tok%d" % p, E[x[:, p]]) for p in range(6)]
    h = np.stack([tok[p] @ T + P[p] for p in range(6)], 1)                 # embed
    s0 = h @ A0 @ h.transpose(0, 2, 1)
    a0 = np.exp(s0 - s0.max(-1, keepdims=True)); a0 /= a0.sum(-1, keepdims=True)
    a0 = iv("a0", a0.reshape(B, 36)).reshape(B, 6, 6)                      # attn0.pattern
    d0 = iv("d0", np.einsum("bqk,bkd->bqd", a0, h @ VO0).reshape(B, 48))
    d0 = d0.reshape(B, 6, 8)                                               # attn0.out
    r0 = iv("r0", (h + d0).reshape(B, 48)).reshape(B, 6, 8)                # resid0.mid
    s1 = r0 @ A1 @ r0.transpose(0, 2, 1)
    a1 = np.exp(s1 - s1.max(-1, keepdims=True)); a1 /= a1.sum(-1, keepdims=True)
    a1 = iv("a1", a1.reshape(B, 36)).reshape(B, 6, 6)                      # attn1.pattern
    d = r0[:, 5] @ G + np.einsum("bk,bkd->bd", a1[:, 5], r0 @ H)           # 3 class differences
    return np.concatenate([np.zeros((B, 1)), d, np.full((B, 2), -(10 ** 9))], 1)

ALIGN = {"tok%d" % p: ["embed"] for p in range(6)}
ALIGN.update({"a0": ["attn0.pattern"], "d0": ["attn0.out"], "r0": ["resid0.mid"], "a1": ["attn1.pattern"]})
